// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 fund) public {
        fund = bound(fund, 0, 1 ether);
        vm.deal(caller, fund);

        if (fund > 0) {
            vm.prank(caller);
            (bool s, ) = address(c).call{value: fund}("");
            require(s);
        }

        uint256 balBefore = address(c).balance;

        bool ok;
        vm.prank(caller);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = c.owner();

        if (caller != owner) {
            uint256 balAfter = address(c).balance;
            assertTrue(balAfter >= balBefore);
        } else {
            assertTrue(true);
        }
    }
}
